-- Gerado por python -m pipelines.generate_dbt; não editar manualmente.
SELECT *,
CASE WHEN TRIM(`SG_UF`) REGEXP '^[0-9]{1,9}([.]0+)?$' THEN CAST(SUBSTRING_INDEX(TRIM(`SG_UF`), '.', 1) AS SIGNED) END AS n_SG_UF,
CASE WHEN TRIM(`SG_UF_NOT`) REGEXP '^[0-9]{1,9}([.]0+)?$' THEN CAST(SUBSTRING_INDEX(TRIM(`SG_UF_NOT`), '.', 1) AS SIGNED) END AS n_SG_UF_NOT,
CASE WHEN TRIM(`ID_MN_RESI`) REGEXP '^[0-9]{1,9}([.]0+)?$' THEN CAST(SUBSTRING_INDEX(TRIM(`ID_MN_RESI`), '.', 1) AS SIGNED) END AS n_ID_MN_RESI,
CASE WHEN TRIM(`ID_RG_RESI`) REGEXP '^[0-9]{1,9}([.]0+)?$' THEN CAST(SUBSTRING_INDEX(TRIM(`ID_RG_RESI`), '.', 1) AS SIGNED) END AS n_ID_RG_RESI,
CASE WHEN TRIM(`ID_UNIDADE`) REGEXP '^[0-9]{1,9}([.]0+)?$' THEN CAST(SUBSTRING_INDEX(TRIM(`ID_UNIDADE`), '.', 1) AS SIGNED) END AS n_ID_UNIDADE,
CASE WHEN TRIM(`ID_MUNICIP`) REGEXP '^[0-9]{1,9}([.]0+)?$' THEN CAST(SUBSTRING_INDEX(TRIM(`ID_MUNICIP`), '.', 1) AS SIGNED) END AS n_ID_MUNICIP,
CASE WHEN TRIM(`ID_REGIONA`) REGEXP '^[0-9]{1,9}([.]0+)?$' THEN CAST(SUBSTRING_INDEX(TRIM(`ID_REGIONA`), '.', 1) AS SIGNED) END AS n_ID_REGIONA,
CASE WHEN TRIM(`NU_IDADE_N`) REGEXP '^[0-9]{1,9}([.]0+)?$' THEN CAST(SUBSTRING_INDEX(TRIM(`NU_IDADE_N`), '.', 1) AS SIGNED) END AS n_NU_IDADE_N,
CASE WHEN TRIM(`CLASSI_FIN`) REGEXP '^[0-9]{1,9}([.]0+)?$' THEN CAST(SUBSTRING_INDEX(TRIM(`CLASSI_FIN`), '.', 1) AS SIGNED) END AS n_CLASSI_FIN,
CASE WHEN TRIM(`CRITERIO`) REGEXP '^[0-9]{1,9}([.]0+)?$' THEN CAST(SUBSTRING_INDEX(TRIM(`CRITERIO`), '.', 1) AS SIGNED) END AS n_CRITERIO,
CASE WHEN TRIM(`EVOLUCAO`) REGEXP '^[0-9]{1,9}([.]0+)?$' THEN CAST(SUBSTRING_INDEX(TRIM(`EVOLUCAO`), '.', 1) AS SIGNED) END AS n_EVOLUCAO,
CASE WHEN TRIM(`CS_GESTANT`) REGEXP '^[0-9]{1,9}([.]0+)?$' THEN CAST(SUBSTRING_INDEX(TRIM(`CS_GESTANT`), '.', 1) AS SIGNED) END AS n_CS_GESTANT,
CASE WHEN TRIM(`CS_RACA`) REGEXP '^[0-9]{1,9}([.]0+)?$' THEN CAST(SUBSTRING_INDEX(TRIM(`CS_RACA`), '.', 1) AS SIGNED) END AS n_CS_RACA,
CASE WHEN TRIM(`CS_ESCOL_N`) REGEXP '^[0-9]{1,9}([.]0+)?$' THEN CAST(SUBSTRING_INDEX(TRIM(`CS_ESCOL_N`), '.', 1) AS SIGNED) END AS n_CS_ESCOL_N,
CASE WHEN TRIM(`TPAUTOCTO`) REGEXP '^[0-9]{1,9}([.]0+)?$' THEN CAST(SUBSTRING_INDEX(TRIM(`TPAUTOCTO`), '.', 1) AS SIGNED) END AS n_TPAUTOCTO,
CASE WHEN TRIM(`DOENCA_TRA`) REGEXP '^[0-9]{1,9}([.]0+)?$' THEN CAST(SUBSTRING_INDEX(TRIM(`DOENCA_TRA`), '.', 1) AS SIGNED) END AS n_DOENCA_TRA,
CASE WHEN TRIM(`DT_NOTIFIC`) REGEXP '^[1-9][0-9]{3}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$'
        THEN CASE WHEN CAST(RIGHT(TRIM(`DT_NOTIFIC`), 2) AS UNSIGNED) <= DAY(LAST_DAY(STR_TO_DATE(CONCAT(LEFT(TRIM(`DT_NOTIFIC`), 7), '-01'), '%Y-%m-%d')))
        THEN STR_TO_DATE(TRIM(`DT_NOTIFIC`), '%Y-%m-%d') END END AS d_DT_NOTIFIC,
CASE WHEN TRIM(`DT_SIN_PRI`) REGEXP '^[1-9][0-9]{3}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$'
        THEN CASE WHEN CAST(RIGHT(TRIM(`DT_SIN_PRI`), 2) AS UNSIGNED) <= DAY(LAST_DAY(STR_TO_DATE(CONCAT(LEFT(TRIM(`DT_SIN_PRI`), 7), '-01'), '%Y-%m-%d')))
        THEN STR_TO_DATE(TRIM(`DT_SIN_PRI`), '%Y-%m-%d') END END AS d_DT_SIN_PRI,
CASE WHEN TRIM(`DT_ENCERRA`) REGEXP '^[1-9][0-9]{3}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$'
        THEN CASE WHEN CAST(RIGHT(TRIM(`DT_ENCERRA`), 2) AS UNSIGNED) <= DAY(LAST_DAY(STR_TO_DATE(CONCAT(LEFT(TRIM(`DT_ENCERRA`), 7), '-01'), '%Y-%m-%d')))
        THEN STR_TO_DATE(TRIM(`DT_ENCERRA`), '%Y-%m-%d') END END AS d_DT_ENCERRA
FROM {{ ref('stg_zika_unica') }}
